function showOnGoogle(id){mapFocus=null;if(isMobile())applyMobileView('map');const c=coordinate(id);if(c&&map){setMapMode('route');mapFocus={point:c,zoom:16};map.setView(c,16);$('#map').scrollIntoView({block:'center',behavior:'smooth'});}else if(geo[id]?.candidates?.length&&map){setMapMode('route');mapFocus={bounds:geo[id].candidates.map(c=>c.feature.geometry.coordinates.slice().reverse())};map.fitBounds(L.latLngBounds(geo[id].candidates.map(c=>c.feature.geometry.coordinates.slice().reverse())),{padding:[40,40],maxZoom:16});toast('Маркеры ? — варианты. Нажмите, чтобы выбрать место.');$('#map').scrollIntoView({block:'center',behavior:'smooth'});}else{googlePlaceId=id;setMapMode('google');toast('Координат пока нет — открываем поиск Google по названию.');$('#googleFrame').scrollIntoView({block:'center',behavior:'smooth'});}}
